"""One-time reviewed source input; merged into the maintained mechanism registry."""
BASE='https://docs.aws.amazon.com/securityagent/latest/userguide/'
SOURCES={
'SS401':(BASE+'about-integrations.html','Account registrations, space resource selection and separate write opt-ins'),
'SS402':(BASE+'perform-penetration-test.html','Target/access/exclusion distinction, credentials and saved assessment'),
'SS403':(BASE+'provide-testing-credentials.html','Credential resolution and retained login procedure; navigation/authentication coverage differs across retrieved page versions'),
'SS404':(BASE+'understand-lifecycle.html','Configuration/run models and one-off design reviews'),
'SS405':(BASE+'review-penetration-findings.html','Findings, confidence filter, original/latest edits and Findings Personalization; newer indexed official page reviewed'),
'SS406':(BASE+'remediate-finding.html','Private repository proposals and S3 diffs; newer indexed provider wording supersedes older GitHub-only description'),
'SS407':(BASE+'revalidate-findings.html','Selected finding replay, Active/Resolved results and preserved lineage'),
'SS408':(BASE+'security-requirements.html','Pack applicability, evaluation and future-review scope'),
'SS409':(BASE+'import-security-requirements.html','Generation replaces pack contents including manual requirements'),
'SS410':(BASE+'quickstart-code-review.html','Source selection, scan modes and preflight'),
'SS411':(BASE+'review-code-findings-github.html','Change triggers and repository filtering guidance'),
'SS412':(BASE+'review-design-findings.html','Design statuses including Insufficient data and clone/new review behavior'),
'SS413':(BASE+'quickstart-threat-model.html','Scope documents, source context, system overview and threat review'),
'SS414':(BASE+'cicd-pentest.html','Saved test prerequisite, CI/CD mode, OIDC, deployed-change scope and server-side execution'),
'SS415':(BASE+'connect-jira.html','Project selection and separate issue/comment permissions'),
'SS416':(BASE+'export-findings-to-issue-tracker.html','One issue per selected finding and Task issue-type prerequisite'),
'SS417':(BASE+'remove-jira.html','Removal blocks future integration actions without deleting existing issues'),
'SS418':(BASE+'quickstart.html','Save versus execute, preflight and result inspection'),
}
DETAILS={}
def add(id,section,kind,inputs,narrative,setup,lifecycle,controls,output,unknown,test,claims):
    DETAILS[id]={'primary_section':section,'kind':kind,'inputs':inputs,'narrative':narrative,'configuration':setup,'lifecycle':lifecycle,'controls':controls,'observable_output':output,'undocumented':unknown,'test':test,'claims':[{'source':s,'section':h,'assertion':a} for s,h,a in claims]}

add('MX-S-CONTEXT','S-M07','Assessment-context mechanism',
'Connected source/document resources, selected revision or design scope, service-role access and assessment configuration.',
['Registration authorizes a provider account; connecting particular resources supplies application-specific evidence. A selected repository can support several assessment types without being independently registered for each. Context assembly must nevertheless use the correct application and revision.',
'Read access and publication of comments or proposed changes are separate. A context read can help interpret an application without creating a permission to change its repository. The service documentation describes the evidence inputs but not a universal persistent knowledge store or retrieval algorithm for every assessment.'],
[['Register','Integrations: authorize the supported provider account.','Account-level registration'],['Connect','Within the intended Agent Space, select repositories or documentation resources.','Application-scoped evidence'],['Configure effects','Review per-repository write options separately from source reads.','Optional repository effects']],
[['Provider registered','Connect resource to space','Read context becomes available through that association.'],['Application changes','Start assessment against intended sources','A previous result remains tied to its earlier evidence.'],['Write option disabled','Run eligible read analysis','Read context does not imply comment or repair permission.']],
'Keep application boundary and revision explicit. Private source-control access is separate from private target access.',
'Selected resource identity and assessment source/preflight evidence.',
'Cross-assessment cache freshness, internal ranking and automatic refresh guarantees are not established.',
['Select a repository and design document that describe one known staging application.','Check that a run identifies that application and revision.','Supply a mismatched design revision and require an explicit mismatch rather than a merged invented architecture.'],
[('SS401','Register once, reuse everywhere; One connection, shared across capabilities','Registration, resource association and write opt-ins are distinct.')])

add('MX-S-ACCESS','S-03','Target-selection and reachability mechanism',
'Verified target domains, supporting accessible domains, excluded paths, applicable VPC route and authorized test scope.',
['The test configuration separates attack targets from supporting navigation and excluded paths. A login provider can be reachable without becoming a vulnerability-testing target. A private route supplies connectivity; it does not widen the scope approved by the application owner.',
'Treat reachability as a prerequisite. If a target cannot be reached, the missing result is a coverage gap. Broadening the target list or removing an exclusion is a scope change, not a routine network troubleshooting shortcut.'],
[['Target','Create/edit penetration test: select verified target URLs.','Active test surface'],['Supporting access','List necessary accessible URLs separately.','Navigation support, not attack targets'],['Exclusions and network','Configure excluded paths and the approved VPC connectivity when required.','Scope and network controls']],
[['Configuration saved','Preflight/connection attempted','Reachability is checked before meaningful target testing.'],['Target unreachable','Correct approved route or name resolution','Rerun the prerequisite check without broadening authorization.'],['Scope changed','Review authorization and save configuration','A future run has a different assessment surface.']],
'Ownership verification and network reachability are not substitutes for owner authorization. Active tests can change application state.',
'Preflight outcome and records of the actual target and paths reached.',
'The sources do not establish that every reachable path is exercised or that every excluded interaction has a uniform implementation across all targets.',
['Use a non-production target, supporting login host and an explicit excluded fixture path.','Verify target access and intended application role.','A denied path or unresolved target must not produce a claim of assessed coverage.'],
[('SS402','Configure penetration test scope; Configure VPC resources','Targets, supporting accessible URLs and excluded paths have different purposes.'),('SS418','Review penetration test findings','Failed preflight stops testing and must be inspected separately.')])

add('MX-S-AUTH','S-M01','Credential-resolution and login mechanism',
'Credential strategy, permitted source resource, access URL, application login instructions and representative test identity.',
['Authentication has two stages: retrieve or obtain the credential, then apply it to the application. Secrets Manager or Lambda can succeed while application login fails. The credential name therefore needs to remain associated with the role and protected paths actually reached.',
'The login instructions describe how to apply the returned value, not how to bypass an inaccessible identity provider. Use the credential mechanisms currently exposed in the test configuration; older and newer retrieved documentation differ on some authentication options. Do not treat that difference as evidence that every deployed interface supports the same flow.'],
[['Strategy','Choose direct input or a documented AWS-native strategy in the test credential configuration.','Credential source'],['Permissions','For Secrets Manager, scope GetSecretValue and DescribeSecret; for Lambda, scope InvokeFunction.','Resource-resolution authority'],['Application step','Provide access URL and login instructions; verify the resulting identity before interpreting findings.','Authenticated surface']],
[['Credential source configured','Resolve credential','Credential value is obtained or resolution fails.'],['Credential resolved','Navigate/apply login','Application session succeeds or login fails.'],['Credential rotated or login changed','Repeat authentication verification','Source success does not establish current application access.']],
'The credential guide requires same-account Secrets Manager/Lambda resources and a credential Lambda completing within 30 seconds. Never place secrets in the documentation examples.',
'Resolution and login evidence plus actual application role; secret contents are not required in retained review evidence.',
'The documentation does not establish one universal authentication policy, retry algorithm or credential-refresh behavior for all applications.',
['Use a disposable customer-role account and a known protected staging route.','Record resolution success and the actual role reaching the route.','Use an expired test credential: distinguish source-read success from failed login.'],
[('SS403','Use advanced setting; Configure multiple credentials','Resource retrieval and application login are separate; strategy-specific permissions and limits apply.')])

add('MX-S-LOGIN','S-M02','Learned authentication-procedure mechanism',
'Configured test credentials, a successfully discovered login flow and the Login Optimization setting.',
['Successful navigation produces a reusable login procedure. Later login sessions can read that procedure instead of rediscovering the path. Reuse concerns navigation; it does not establish that an old credential remains valid or that the application still assigns the intended role.',
'This is separate from finding personalization and vulnerability revalidation. A changed login flow calls for a fresh authentication check, while a changed vulnerability calls for assessment or revalidation. Switching off reuse is not a documented deletion of learned material.'],
[['Prerequisite','Configure a credential and complete a successful login.','Procedure-production input'],['Reuse','Inspect Login Optimization in the penetration-test configuration; the documentation identifies it as enabled by default.','Reuse control'],['Verification','On later sessions, verify authenticated identity independently from any observable reuse.','Coverage prerequisite']],
[['No successful login procedure','Successful navigation','A reusable skill file is produced.'],['Procedure retained; reuse enabled','Later login','Saved navigation can be applied.'],['Reuse disabled','Later login','Reuse stops; retained learning is preserved.'],['Reuse re-enabled','Later login','Retained procedure becomes applicable again.']],
'Test current credentials and role on each relevant run. Retained navigation is not a general-purpose incident memory.',
'Authenticated session and, where exposed, evidence of reuse. Do not infer reuse solely from faster execution.',
'No independent public CRUD API or guaranteed invalidation policy for the saved login skill is established.',
['Use an authorized multistep staging login.','Compare first and later logins while verifying the same application role.','Change the login form; failure to reach the protected route remains a coverage gap.'],
[('SS403','Login Optimization','Successful navigation produces a skill reused in later sessions/runs; disabling reuse preserves learning.')])

add('MX-S-RUN','S-04','Configuration-to-assessment workflow',
'Saved penetration-test configuration, current target deployment, credentials, exclusions and execution/work limit.',
['A saved penetration-test configuration is reusable; each execution has its own record and findings. Saving the configuration does not freeze a deployment that continues to change. Identify the deployed revision and current credentials for every run.',
'Execution begins with prerequisite checks before assessment work. A preflight failure is neither a successful clean assessment nor evidence that the target contains no vulnerabilities. The assessment record should retain incomplete areas along with findings.'],
[['Define','Penetration tests → create: configure target, role, credentials, network and source context.','Reusable configuration'],['Save or start','Choose the supported save-only or create-and-execute action.','Definition versus run'],['Inspect','Open the run overview, preflight/logs and findings.','Execution evidence']],
[['Configuration saved','Start execution','An independent run is created.'],['Preflight fails','Resolve prerequisite and start a new run','No successful runtime coverage is established.'],['Run completes','Review findings and coverage','Further execution uses a new run, not rewritten evidence.']],
'Work limits, test scope and owner authorization must remain explicit; budget limits do not guarantee a particular coverage level.',
'Run identity, actual target context, logs, discovered/tested endpoints and findings.',
'The documented interface does not expose the complete assessment-planning or vulnerability-discovery algorithm.',
['Use a deliberately limited staging target and record its deployed revision.','Inspect actual reached paths and completed phases.','Make a required target unreachable; require a preflight failure or explicit coverage gap.'],
[('SS404','Penetration testing: reusable configurations with independent executions','One configuration supports separate runs and new findings.'),('SS418','Create and execute; Review findings','Saving, executing and preflight outcomes are different stages.')])

add('MX-S-FINDING','S-05','Evidence-inspection and disposition workflow',
'Finding identifier, current/original attributes, validation evidence, assessment revision and application-owner context.',
['A finding combines an observation with an interpretation of risk. Inspect the supporting request, response or source evidence before accepting that interpretation. The findings view can hide unverified items, so the visible count depends on the active filter.',
'Editing a finding changes its recorded attributes; it does not repair the application. The separately documented Findings Personalization mechanism can also influence later similar findings. Read the original and latest values when determining whether a change reflects new vulnerability evidence or a revised organizational preference.'],
[['Inspect','Completed/in-progress run → Findings → select finding and trace its actions/logs.','Evidence and affected context'],['Visibility','Review the unverified-findings filter before counting results.','Display scope'],['Disposition','Review current and original values where edits exist.','Human decision versus generated attributes']],
[['Finding observed','Inspect evidence','Confidence and supported impact can be assessed.'],['Finding edited','Save current values','Latest attributes change; original view remains available.'],['Repair proposed','Review/deploy/verify separately','An edited status does not establish deployed remediation.']],
'Generated reproduction scripts require review and an authorized target before execution. Finding counts and severity alone do not establish risk or coverage.',
'Finding identity, supporting evidence, original/latest values and a reviewer disposition.',
'No calibrated probability interpretation of confidence or exhaustive false-negative rate is established.',
['Use the synthetic authorization-finding fixture for a tabletop.','Trace the claim to the supplied identity, request and affected revision.','Hide/unhide unverified findings and verify that changed visibility is not reported as remediation.'],
[('SS405','Default confidence filter; Review finding details; View original agent version','Evidence, display filtering and original/latest attributes are distinct review surfaces.')])

add('MX-S-PERSONALIZE','S-05','Learned finding-preference mechanism',
'Eligible operator edits in the most recent completed penetration-test run and Findings Personalization enabled when the test starts.',
['Findings Personalization learns eligible edits and applies preferences to similar findings on later runs. It is distinct from discovering vulnerabilities, retaining a login procedure and replaying a finding. Learned changes can alter finding attributes without proving that application behavior changed.',
'Inspect the Personalization changes explanation and original values before interpreting a severity change. For status, the documented learnable signal is marking a finding FALSE_POSITIVE; other status updates are not equivalent learning inputs.'],
[['Enablement','Inspect Findings Personalization in the penetration-test configuration; documented default is enabled.','Must be enabled at test start for learning'],['Eligible input','Review edits in the most recent completed run.','Not arbitrary edits from all historical runs'],['Inspection','Compare original/latest attributes and Personalization changes where shown.','Observed preference application']],
[['Eligible edited finding','Next applicable run','Similar findings can receive personalized attributes.'],['Later edit','Subsequent learning','Most recent edit replaces the earlier preference.'],['Feature disabled','Run without personalization','Raw agent-produced findings are shown; preferences remain retained.']],
'Personalized severity is not evidence of a repaired vulnerability. Disabling the feature is not deleting learned preferences.',
'Original/latest attributes and a Personalization changes explanation on affected findings.',
'Similarity thresholds, internal preference storage and a public preference CRUD resource are not established by the guide.',
['Use a controlled staging finding whose risk context can be changed without modifying the application.','Inspect whether a later similar finding exposes the personalization change.','Disable personalization; compare raw output without claiming that retained preferences were deleted.'],
[('SS405','How personalization learns from your edits; Enable or disable Findings Personalization','Learning uses eligible edits from the most recent completed run; false-positive status is special, and disabling preserves preferences.')])

add('MX-S-FIX','S-05','Remediation-proposal workflow',
'Finding, eligible connected repository or S3 source, configured remediation permission and selected source context.',
['Remediation produces a proposed source change. Current provider guidance describes pull/merge requests for eligible private repositories and a downloadable diff for S3 sources. Older retrieved text describes a narrower provider/public-repository path; do not generalize either wording to unsupported provider writes.',
'The proposal remains separate from review, merge, deployment and finding revalidation. Preserve the original finding relationship through those steps, including any linked Jira record.'],
[['Enable','Enable remediation in the administrative configuration and select the appropriate repositories/source.','Optional source-write capability'],['Start','From the finding, choose Remediate code or use the configured automatic proposal path.','Remediation attempt'],['Review','Inspect proposal/diff and its tests before normal deployment.','Team acceptance']],
[['Finding confirmed','Remediation requested','Attempt and proposed change are produced.'],['Proposal created','Engineering review','Accept, revise or reject without implying deployment.'],['Repair deployed','Revalidate finding separately','Test the actual target rather than the branch.']],
'Read-only source access does not grant proposal-write permission. A pull request is not an automatically deployed fix.',
'Remediation status, linked proposal/diff and original finding identity.',
'No universal guarantee of successful repair, regression coverage or automatic deployment is provided.',
['Use a known authorized fixture finding and isolated test repository.','Inspect intended diff, tests and unrelated changes.','A failing build or undeployed merge must keep verification incomplete.'],
[('SS406','Start and view code remediation','Current guidance distinguishes private-repository proposals and S3 diffs.'),('SS401','Write actions are opt-in','Repository writes are separately configured and provider-limited.')])

add('MX-S-REVALIDATE','S-M05','Targeted replay and lineage mechanism',
'Completed test findings, deployed repair on the original target and current authentication configuration.',
['Revalidation repeats validation steps for selected existing findings and creates a separate job. The original finding remains available and the result links back to it. This is targeted replay, not new vulnerability discovery.',
'An Active result means reproduction succeeded. Resolved means the service could not reproduce the issue during this replay. The engineering review must still confirm that the intended identity and path were reached; a failed login cannot demonstrate a repaired authorization check.'],
[['Prepare','Deploy the reviewed repair to the environment originally tested.','Current target state'],['Select','Completed run → Multiselect findings for revalidation → select findings → Revalidate findings.','Selected replay scope'],['Inspect','Open the job, original finding and revalidation history.','Evidence lineage']],
[['Original finding','Start revalidation','Separate job created.'],['Validation reproduced','Active result','Further remediation remains necessary.'],['Validation not reproduced','Resolved result','Interpret within reached identity and scope.'],['Another repair deployed','Repeat selected replay','A further linked job records a new attempt.']],
'Full assessments remain necessary for broader changes; replay does not certify whole-application security.',
'Linked job and per-finding replay result; linked Jira issues can receive result comments.',
'No exactly-once callback or universal guarantee distinguishing every environmental failure from non-reproduction is established.',
['Use a deployed repair with a known test identity and retained original finding.','Check the reached identity and link to the replay result.','Break authentication in a controlled test; record verification as inconclusive rather than celebrating non-reproduction.'],
[('SS407','Select findings; Interpret results; Trace history','Replay has separate job identity, selected scope and preserved original finding.')])

add('MX-S-CRITERIA','S-M03','Requirement-applicability mechanism',
'Enabled pack, requirement applicability/compliance definitions and eligible source/design review evidence.',
['Requirement evaluation first needs a criterion that applies to the subject. The compliance assessment then compares the supplied evidence with that criterion. Missing evidence is not the same as a demonstrated violation or an inapplicable requirement.',
'Packs are shared policy configuration. Enabling, disabling or editing one affects future eligible reviews, not the historical conclusions of reviews already completed. This shared reach makes requirement maintenance a cross-application change.'],
[['Define','Security requirements → chosen pack → inspect applicability, compliance criteria and optional remediation guidance.','Evaluation rule'],['Enable','Enable the reviewed pack and select requirement evaluation in the eligible review mode.','Future assessment behavior'],['Inspect','Review the stated reason for applicability and result.','Criterion-level evidence']],
[['Pack disabled','Enable','Criteria apply to new eligible reviews.'],['Requirement edited','Start new review','Updated criteria apply prospectively.'],['Existing result','Pack changed','Historical review is not rewritten.']],
'Framework labels and managed packs are not compliance certification; applicability is part of the evaluated claim.',
'Requirement-linked result and explanation, including missing-data or inapplicable distinctions where exposed.',
'Full semantic evaluation rules and a deterministic false-positive/false-negative guarantee are not documented.',
['Prepare compliant, violating and deliberately inapplicable examples for one requirement.','Check applicability before the compliance verdict.','Remove decisive design evidence; require an insufficient-evidence interpretation, not assumed compliance.'],
[('SS408','Overview; Enable or disable a pack','Enabled packs govern future eligible reviews and have distinct applicability/compliance fields.'),('SS412','Understand compliance statuses','Design reviews distinguish Insufficient data and Not applicable from compliance/violation.')])

add('MX-S-GENERATE','S-M04','Requirement-replacement mechanism',
'Approved policy documents, chosen custom pack and existing requirements including manually authored entries.',
['Generation reads policy documents and constructs structured requirements. Running it again for an existing pack replaces the requirements; it is not an append operation. A successful generation therefore establishes a proposed replacement, not approval of every generated rule.',
'Reconcile overlapping policies before submission. Review applicability and technical criteria afterward, and explicitly compare the replacement with any manual entries that existed before the upload.'],
[['Select','Security requirements → Custom packs → choose/create the intended pack.','Replacement target'],['Generate','Upload supported documents and choose Generate requirements; acknowledge replacement when applicable.','Generation operation'],['Accept','Review/edit resulting requirements before enabling the pack for later assessments.','Team approval of generated criteria']],
[['Pack has requirements','Regenerate from new documents','Existing requirements, including manual ones, are replaced.'],['Generation in progress','Attempt another upload','The documented workflow blocks another upload until processing finishes.'],['Generated criteria','Review and enable','New eligible reviews use the accepted configuration.']],
'Keep authoritative policy and reviewed configuration in Git; do not treat a generated pack as the only source of policy.',
'Generated requirement definitions and prospective pack state.',
'Automatic merge of old/manual rules and transactional rollback are not documented.',
['Use a disposable pack containing one manual rule and an approved small policy fixture.','Compare resulting criteria with source and prior contents.','Confirm replacement behavior without using a production policy pack.'],
[('SS409','Generate requirements; Replace requirements with a new upload','Generation replaces existing pack contents and requires review before use.')])

add('MX-S-CODE','S-06','Source-analysis workflow',
'Exact source revision, full/differential scope, selected review modes, enabled requirements and source-access role.',
['Full-source and change-focused reviews use related analysis but different evidence boundaries. Preflight must first obtain the source and prepare the environment. A failure at that stage is not a clean scan.',
'Repository-event settings and optional comments are distinct from a manually started full review. The documented filtering file is read from the repository main branch, so changing it only in an unmerged branch may not change the current review behavior.'],
[['Full review','Web app → Code reviews → create: select sources and role; Start review.','Saved source assessment'],['Modes','Select vulnerability findings, requirement evaluation or both.','Analysis criteria'],['Change guidance','Review supported provider triggers and .awssecurityagent/filtering.md on the main branch.','Change scope and filtering']],
[['Review requested','Preflight','Source/environment prerequisites checked.'],['Preflight fails','Fix access and start a new run','Static analysis has not completed.'],['Source revision changes','Supported new review/reanalysis','Prior findings remain revision-specific.']],
'Read analysis, posted comments and proposed repairs are different effects. Excluded source is unassessed, not verified safe.',
'Preflight results, reviewed revision, findings and any configured provider comments.',
'No complete vulnerability-discovery algorithm or exhaustive language/framework coverage is inferred from a successful run.',
['Review a known source fixture with exact commit identity.','Check that findings reference the expected revision and modes.','Deny source access or exclude a known fixture path; retain the resulting assessment gap.'],
[('SS410','Create and run a code review; Review findings','Source preflight precedes analysis and has inspectable failure outcomes.'),('SS411','How code review works; Filtering findings','Change-trigger and main-branch filtering behavior are distinct configuration paths.')])

add('MX-S-DESIGN','S-06','Point-in-time design-review workflow',
'Current design documents, application context and enabled security criteria.',
['Design review evaluates a submitted description of the system. It does not observe whether the deployed implementation actually enforces that description. The review must distinguish a requirement violation from missing design evidence.',
'Its lifecycle is one-off rather than a reusable test configuration. Clone or create a new review for revised material so the earlier result remains attributable to its original documents.'],
[['Submit','Select the design-review workflow and current design material.','Point-in-time subject'],['Inspect','Open findings by requirement and read the compliance explanation.','Criteria and evidence'],['Revise','Clone/create a new review with updated material.','Independent later assessment']],
[['Design submitted','Review','Requirement-level findings produced.'],['Evidence insufficient','Add the missing design information','Prepare a new assessment, not a fabricated pass.'],['Design revised','Clone/new review','New point-in-time result; original review remains separate.']],
'Design compliance is not implementation verification.',
'Reviewed files, requirement result and explanation.',
'Automatic refresh of existing design reviews and continuous synchronized system models are not documented.',
['Use a design fixture with an explicit identity boundary and one omitted control.','Verify the difference between violation and insufficient evidence.','Revise the document without rerunning; the old result must not be presented as a new assessment.'],
[('SS404','Key differences between security capabilities','Design reviews have a different one-off lifecycle.'),('SS412','Understand statuses; Next steps','Missing evidence and non-compliance differ; cloning creates a new review.')])

add('MX-S-THREAT','S-06','System-model and threat-analysis workflow',
'Scope documents, selected sources or both, application boundary and service role.',
['Scope documents express what should be modeled; source code supplies context for the current system. The output includes a system overview and threats derived for that representation. Review the system boundary and flows before accepting the threats built on them.',
'A model of the wrong system can produce plausible but irrelevant threats. Correct the scope or source mismatch and run again rather than dismissing every downstream item individually.'],
[['Create','Threat models → Create threat model: title, scope documents and/or sources, service role and optional log group.','Reusable model configuration'],['Execute','Start run; inspect Preflight and Logs.','Independent run'],['Review','Inspect Overview before Threats; review evidence and recommendations.','System representation and threat records']],
[['Configuration saved','Start run','Preflight and analysis create a system model.'],['Model produced','Review boundaries and threats','Accept, resolve or dismiss findings with rationale.'],['Scope changes','Rerun with corrected input','New result reflects the intended subject.']],
'Inferred relationships require owner review; threat status is not proof that a mitigation is deployed.',
'System overview, threat statements, classifications, evidence and recommendations.',
'The exhaustive threat-generation strategy and completeness of inferred flows are not published.',
['Provide a small design with a known trust boundary and supporting source.','Check that the overview reflects the known boundary.','Use a deliberately stale scope document; identify the mismatch before interpreting threat counts.'],
[('SS413','Create and run a threat model; Review threats','Scope documents and source context have distinct roles; overview and threats are reviewable.')])

add('MX-S-PIPELINE','S-06','Post-deployment invocation mechanism',
'Existing penetration-test configuration with CI/CD mode, source connection, pipeline OIDC identity and deployed change identifiers.',
['The pipeline step starts and observes a server-side test of a deployed change. It does not create the application or replace the saved assessment scope, and it does not run the penetration-testing engine inside the delivery runner.',
'Configure the release decision before enabling the integration. Invocation failure, unfinished assessment and a completed result above the selected severity threshold need distinct handling. This decision policy is authored team behavior, not a claim that every pipeline fails closed automatically.'],
[['Prerequisite','Verify target and create a test with current credentials/network scope; enable CI/CD mode and record space/test IDs.','Existing assessment definition'],['Identity','Configure the provider-specific OIDC path and supported integration step.','Short-lived pipeline authentication'],['Decision','Set accepted threshold and explicit behavior for missing/incomplete results.','Team promotion policy']],
[['Deployment completed','Authorized integration step','Server-side assessment job starts.'],['Job running','Pipeline waits/observes','Runner completion is not yet assessment completion.'],['Job result available','Apply declared gate','Promote, block or escalate using that result and revision.']],
'This preview path is post-deployment assessment, not pull-request static analysis.',
'Pipeline execution, deployed change, assessment job and applied promotion decision.',
'Exactly-once invocation, universal timeout behavior and identical provider semantics are not established.',
['Use a non-production pipeline with known deployed revision and saved assessment.','Retain the server job ID with the gate result.','Simulate unavailable/incomplete result; follow the declared blocking/escalation rule rather than passing silently.'],
[('SS414','Before you start; Post-deployment gate','The integration invokes an existing configured test, uses OIDC and observes server-side work.')])

add('MX-S-JIRA','S-09','Finding-publication mechanism',
'Connected Jira Cloud site, permitted project/actions, selected finding and reviewed disclosure scope.',
['A site registration supplies authorization; a project connection chooses where the Agent Space can create issues or comments. Creating an issue publishes a finding into an external system with its own audience and lifecycle.',
'The link matters later: remediation proposals and revalidation outcomes can be attached to the same issue through supported behavior. Removing the integration stops future actions but does not remove tickets already created.'],
[['Register','Integrations → Add integration → Jira; authorize the Forge app and registration.','Site authorization'],['Bind','Within Agent Space select project and allowed create/comment actions.','Project-specific effects'],['Publish','Select finding(s) and create issues in a project permitting the Task type.','One issue per selected finding']],
[['Finding selected','Create Jira issue','External record and finding relationship created.'],['Linked finding revalidated','Supported result comment','External history updated when permitted.'],['Integration removed','Future publication attempted','No further action through that integration; existing issues remain.']],
'Issue creation and comment permission are separate. Do not import FinOps approval behavior into Security Agent.',
'Actual issue/comment in the intended project and preserved finding link.',
'Automatic duplicate suppression and transactional rollback across AWS and Jira are not established.',
['Use a restricted test project and a non-sensitive finding fixture.','Check audience, issue type and finding link.','Revoke comment permission; distinguish publication failure from assessment failure and avoid blind duplicate retries.'],
[('SS415','Connecting projects to an Agent Space','Create and comment actions are selected per project.'),('SS416','Creating issues for findings','The selected project must allow Task and receives one issue per selected finding.'),('SS417','Prerequisites for removal','Previously created issues are not deleted with the integration.')])
